import{_ as a,o,c as l,a0 as r}from"./chunks/framework.B7o6dWmz.js";const e="/blog-styles/linear.png",i="/blog-styles/raycast.png",s="/blog-styles/anthropic.png",n="/blog-styles/notion.png",h="/blog-styles/ghost.png",u="/blog-styles/nextra.png",c="/blog-styles/astro-themes.png",p="/blog-styles/framer-templates.png",f=JSON.parse('{"title":"博客风格样板 V2（供挑选）","description":"","frontmatter":{},"headers":[],"relativePath":"styles.md","filePath":"styles.md"}'),g={name:"styles.md"};function m(d,t,b,q,_,A){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="博客风格样板-v2-供挑选" tabindex="-1">博客风格样板 V2（供挑选） <a class="header-anchor" href="#博客风格样板-v2-供挑选" aria-label="Permalink to &quot;博客风格样板 V2（供挑选）&quot;">​</a></h1><p>上一版偏&quot;文字极简&quot;，这次按你的要求重新全网找了一批——分两条线：<strong>① 设计感强的品牌站 ② 建站平台 / 模板项目</strong>（GitHub 热门 + 专业模板市场）。截图均为整页实拍。</p><p>你挑 2–3 个喜欢的，我仿照其风格重建本站（配色 / 布局 / 字体 / 文章排版）。</p><hr><h2 id="a-品牌站-设计感强-适合做-高级感-参考" tabindex="-1">A. 品牌站（设计感强，适合做&quot;高级感&quot;参考） <a class="header-anchor" href="#a-品牌站-设计感强-适合做-高级感-参考" aria-label="Permalink to &quot;A. 品牌站（设计感强，适合做&quot;高级感&quot;参考）&quot;">​</a></h2><h3 id="a1-·-linear-—-暗色现代-saas-品牌" tabindex="-1">A1 · Linear — 暗色现代 SaaS 品牌 <a class="header-anchor" href="#a1-·-linear-—-暗色现代-saas-品牌" aria-label="Permalink to &quot;A1 · Linear — 暗色现代 SaaS 品牌&quot;">​</a></h3><ul><li>风格：<strong>深色 + 渐变光晕 + 圆角卡片</strong>，克制而有高级感</li><li>特点：Linear 是硅谷顶级产品团队；博客用「分类标签 + 卡片瀑布流」，技术文章配大图</li><li>适合：AI 工具 / 产品型内容，未来卖产品时气质最搭</li></ul><p><img src="'+e+'" alt="Linear"></p><h3 id="a2-·-raycast-—-暗色精选博客" tabindex="-1">A2 · Raycast — 暗色精选博客 <a class="header-anchor" href="#a2-·-raycast-—-暗色精选博客" aria-label="Permalink to &quot;A2 · Raycast — 暗色精选博客&quot;">​</a></h3><ul><li>风格：<strong>深色 + 大留白 + 头条文章 + 卡片列表</strong></li><li>特点：头条文章突出、次级卡片规整，导航丰富；个人开发者工具品牌范本</li><li>适合：工具实测、产品发布、教程类内容</li></ul><p><img src="'+i+'" alt="Raycast"></p><h3 id="a3-·-anthropic-—-白底大字编辑风" tabindex="-1">A3 · Anthropic — 白底大字编辑风 <a class="header-anchor" href="#a3-·-anthropic-—-白底大字编辑风" aria-label="Permalink to &quot;A3 · Anthropic — 白底大字编辑风&quot;">​</a></h3><ul><li>风格：<strong>纯白背景 + 超大标题 + 编辑杂志式排版</strong></li><li>特点：Claude 官方新闻室；用排版层级和留白营造&quot;专业、可信&quot;</li><li>适合：深度分析、行业观点、官方声明类内容</li></ul><p><img src="'+s+'" alt="Anthropic"></p><h3 id="a4-·-notion-—-亮色内容博客" tabindex="-1">A4 · Notion — 亮色内容博客 <a class="header-anchor" href="#a4-·-notion-—-亮色内容博客" aria-label="Permalink to &quot;A4 · Notion — 亮色内容博客&quot;">​</a></h3><ul><li>风格：<strong>亮色 + 左侧分类栏 + 卡片网格</strong>，插图丰富</li><li>特点：Notion 官方「Tools &amp; Craft」板块，文章带插画、作者、分类</li><li>适合：多栏目运营（AI / 跨境 / GEO / 技术），插画风让内容更亲切</li></ul><p><img src="'+n+'" alt="Notion"></p><hr><h2 id="b-建站平台-模板项目-可以直接用-或抄其设计" tabindex="-1">B. 建站平台 / 模板项目（可以直接用，或抄其设计） <a class="header-anchor" href="#b-建站平台-模板项目-可以直接用-或抄其设计" aria-label="Permalink to &quot;B. 建站平台 / 模板项目（可以直接用，或抄其设计）&quot;">​</a></h2><h3 id="b1-·-ghost-—-内容订阅-会员变现平台" tabindex="-1">B1 · Ghost — 内容订阅 + 会员变现平台 <a class="header-anchor" href="#b1-·-ghost-—-内容订阅-会员变现平台" aria-label="Permalink to &quot;B1 · Ghost — 内容订阅 + 会员变现平台&quot;">​</a></h3><ul><li>建站：Ghost 6.0，开源内容平台</li><li>风格：<strong>白底 + 大号标语 + 产品仪表盘展示</strong>；核心理念「把读者变成生意」</li><li>特点：自带会员 / 付费订阅 / 邮件通讯，<strong>天然适合&quot;内容 + 卖产品&quot;路线</strong></li><li>落地：可自托管，或直接用 Ghost 建站替代 VitePress</li></ul><p><img src="'+h+'" alt="Ghost"></p><h3 id="b2-·-nextra-—-next-js-mdx-建站框架" tabindex="-1">B2 · Nextra — Next.js/MDX 建站框架 <a class="header-anchor" href="#b2-·-nextra-—-next-js-mdx-建站框架" aria-label="Permalink to &quot;B2 · Nextra — Next.js/MDX 建站框架&quot;">​</a></h3><ul><li>建站：Vercel 出品，开源框架（GitHub 6k+ ⭐）</li><li>风格：<strong>文档站式布局</strong>：导航 + 侧栏 + 正文，双栏清晰</li><li>特点：写 Markdown 自动成站，支持暗色模式；适合文档 + 博客混合站</li><li>落地：可无缝迁移现有 VitePress 内容</li></ul><p><img src="'+u+'" alt="Nextra"></p><h3 id="b3-·-astro-themes-—-建站主题市场" tabindex="-1">B3 · Astro Themes — 建站主题市场 <a class="header-anchor" href="#b3-·-astro-themes-—-建站主题市场" aria-label="Permalink to &quot;B3 · Astro Themes — 建站主题市场&quot;">​</a></h3><ul><li>建站：Astro 官方主题库（社区贡献）</li><li>风格：<strong>主题聚合页</strong>，覆盖博客 / 作品集 / SaaS 落地页等几十类</li><li>特点：一站式预览几十种现代博客主题，免费 + 付费都有；<strong>适合在这里挑现成模板</strong></li><li>落地：选中某主题后可直接在 GitHub 拿到源码</li></ul><p><img src="'+c+'" alt="Astro Themes"></p><h3 id="b4-·-framer-templates-—-专业模板市场" tabindex="-1">B4 · Framer Templates — 专业模板市场 <a class="header-anchor" href="#b4-·-framer-templates-—-专业模板市场" aria-label="Permalink to &quot;B4 · Framer Templates — 专业模板市场&quot;">​</a></h3><ul><li>建站：Framer（无代码建站平台）</li><li>风格：<strong>深色模板画廊</strong>，按行业分类（Blogs / AI / SaaS / Agency…），带价格与预览</li><li>特点：大量视觉出众的博客 / 落地页模板，<strong>适合用来&quot;抄&quot;布局和质感</strong></li><li>落地：Framer 免费模板可直接用；付费模板 $99 起</li></ul><p><img src="'+p+'" alt="Framer Templates"></p><hr><blockquote><p>组合建议：</p><ul><li><strong>想要&quot;高级感 + 未来卖产品&quot;</strong>：A1 Linear 或 A2 Raycast 的暗色系</li><li><strong>想要&quot;白底专业编辑风&quot;</strong>：A3 Anthropic</li><li><strong>想要&quot;直接抄模板、快速落地&quot;</strong>：B1 Ghost 或 B3 Astro Themes 里挑</li><li><strong>内容多栏目 + 插画</strong>：A4 Notion</li></ul></blockquote><blockquote><p>注：上一版 7 个（Paul Graham / 阮一峰 / Simon Willison / Vercel / Stripe / Wait But Why / 少数派）已从本站移除；Figma、AstroWind、Tailwind Starter 三个站点本次访问超时/空白，未收录，需要的话可再抓。</p></blockquote>',34)])])}const y=a(g,[["render",m]]);export{f as __pageData,y as default};
